-- ------------------------------------------------------------
-- 12) user_branches — vincula o admin à filial 1 (algumas listagens usam
--     INNER JOIN nessa tabela; sem essa linha o admin some de telas que
--     dependem dela, mesmo sendo Superadm).
--     NOTA: essa tabela não tem chave única em (id_user, id_branch), só o
--     `id` autoincrement — por isso o idempotente aqui é via
--     "INSERT ... SELECT ... WHERE NOT EXISTS", não ON DUPLICATE KEY.
-- ------------------------------------------------------------
SELECT 1, 1
WHERE NOT EXISTS (
  SELECT 1 FROM user_branches WHERE id_user = 1 AND id_branch = 1
);
